impl MulBackend<u64> for NeonDescriptor {
    #[inline(always)]
    fn mul(self, a: uint64x2_t, b: uint64x2_t) -> uint64x2_t {
        neon_call!(self, |a: uint64x2_t, b: uint64x2_t| -> uint64x2_t {
            let a_lo = vmovn_u64(a);
            let b_lo = vmovn_u64(b);
            let lo = vmull_u32(a_lo, b_lo);
            let hi = vmlal_u32(
                vmull_u32(vmovn_u64(vshrq_n_u64::<32>(a)), b_lo),
                a_lo,
                vmovn_u64(vshrq_n_u64::<32>(b)),
            );
            vaddq_u64(lo, vshlq_n_u64::<32>(hi))
        })
    }
}

