impl F32ExtraBackend for NeonDescriptor {
    #[inline(always)]
    fn f32_as_i32(self, a: float32x4_t) -> int32x4_t {
        neon_call!(self, |a: float32x4_t| -> int32x4_t { vcvtq_s32_f32(a) })
    }
    #[inline(always)]
    fn f32_round_store_u8(self, a: float32x4_t, dest: &mut [u8]) {
        neon_call!(self, |a: float32x4_t, dest: &mut [u8]| {
            let u16s = vqmovun_s32(vcvtq_s32_f32(vrndnq_f32(a)));
            let u8s = vqmovn_u16(vcombine_u16(u16s, u16s));
            *dest.first_chunk_mut::<4>().unwrap() =
                vget_lane_u32::<0>(vreinterpret_u32_u8(u8s)).to_ne_bytes();
        });
    }
    #[inline(always)]
    fn f32_round_store_u16(self, a: float32x4_t, dest: &mut [u16]) {
        neon_call!(self, |a: float32x4_t, dest: &mut [u16]| {
            arch_ops::vst1_u16(
                dest.first_chunk_mut().unwrap(),
                vqmovun_s32(vcvtq_s32_f32(vrndnq_f32(a))),
            );
        });
    }
    #[inline(always)]
    fn f32_load_f16_bits(self, mem: &[u16]) -> float32x4_t {
        neon_call!(self, |mem: &[u16]| -> float32x4_t {
            arch_ops::fcvtl_f32_f16(arch_ops::vld1_u16(mem.first_chunk().unwrap()))
        })
    }
    #[inline(always)]
    fn f32_store_f16_bits(self, a: float32x4_t, dest: &mut [u16]) {
        neon_call!(self, |a: float32x4_t, dest: &mut [u16]| {
            arch_ops::vst1_u16(dest.first_chunk_mut().unwrap(), arch_ops::fcvtn_f16_f32(a));
        });
    }
}

